import { test, expect } from '@playwright/test';

test.describe('Login Form Keyboard Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should navigate and submit login form using keyboard', async ({ page }) => {
    // Verify login form is visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Verify input fields are accessible by keyboard
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();

    // Verify login button is visible and accessible
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeVisible();

    // Focus email input using Tab
    await emailInput.press('Tab');
    await expect(emailInput).toHaveFocus();

    // Type email address
    await emailInput.fill('user@example.com');

    // Focus password input using Tab
    await passwordInput.press('Tab');
    await expect(passwordInput).toHaveFocus();

    // Type password
    await passwordInput.fill('password123');

    // Focus login button using Tab
    await loginButton.press('Tab');
    await expect(loginButton).toHaveFocus();

    // Press Enter to submit form
    await loginButton.press('Enter');

    // Verify success message appears
    const successMessage = page.getByText('Login successful');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    const dashboard = page.getByRole('main');
    await expect(dashboard).toBeVisible();
  });

  test('should handle focus trapping within the form', async ({ page }) => {
    // Verify login form is visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Focus email input using Tab
    const emailInput = page.getByLabel('Email Address');
    await emailInput.press('Tab');
    await expect(emailInput).toHaveFocus();

    // Tab through password input
    await passwordInput.press('Tab');
    await expect(passwordInput).toHaveFocus();

    // Tab through login button
    await loginButton.press('Tab');
    await expect(loginButton).toHaveFocus();

    // Press Enter to submit form
    await loginButton.press('Enter');

    // Verify success message appears
    const successMessage = page.getByText('Login successful');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    const dashboard = page.getByRole('main');
    await expect(dashboard).toBeVisible();

    // Verify form is still focused after submission
    await expect(loginForm).toHaveFocus();
  });
});
